assert "result" in globals(), "Сохраните ответ в переменную result."

def test_mse(model, X_tr, y_tr):
    model.fit(X_tr, y_tr)
    return float(np.mean((y_test - model.predict(X_test)) ** 2))

def expected_on(X_tr, y_tr):
    return {
        "ols": test_mse(LinearRegression(), X_tr, y_tr),
        "ridge": test_mse(Ridge(alpha=1.0), X_tr, y_tr),
        "lasso": test_mse(Lasso(alpha=1.0, max_iter=10000), X_tr, y_tr),
    }

pairs = compare_models(X_train, y_train, X_test, y_test)
assert isinstance(pairs, list) and len(pairs) == 3, "Возвращается список из трёх пар."
assert [str(name) for name, _ in pairs] == ["ols", "ridge", "lasso"], "Модели идут в порядке ols, ridge, lasso."
values = {str(name): float(value) for name, value in pairs}
full = expected_on(X_train, y_train)
for name in ("ols", "ridge", "lasso"):
    assert abs(values[name] - full[name]) < 1e-3, f"Ошибка {name} на тесте не совпадает с обученной здесь же моделью."
assert full["ridge"] < full["ols"] < full["lasso"], "Порядок по качеству: ridge лучше ols, а lasso хуже обоих."
assert values["ols"] > 0 and values["ridge"] > 0, "Ошибки считаются на тестовой выборке, а не на обучении."

# На другой обучающей части числа выходят другие: готовый ответ из конспекта не подойдёт.
short = expected_on(X_train[:80], y_train[:80])
short_pairs = compare_models(X_train[:80], y_train[:80], X_test, y_test)
short_values = {str(name): float(value) for name, value in short_pairs}
for name in ("ols", "ridge", "lasso"):
    assert abs(short_values[name] - short[name]) < 1e-3, f"На меньшей обучающей части {name} даёт другую ошибку."
assert abs(short_values["ols"] - full["ols"]) > 1e-3, "Функция обучается на переданных данных, а не возвращает записанные числа."

assert isinstance(result, tuple) and len(result) == 2, "В result — список пар и имя победителя."
assert isinstance(result[0], list) and [str(name) for name, _ in result[0]] == ["ols", "ridge", "lasso"], "В списке те же три модели по порядку."
for name, value in result[0]:
    assert abs(float(value) - full[str(name)]) < 1e-4, "Значения — ошибки на тесте, округлённые до четырёх знаков."
assert str(result[1]) == min(full, key=full.get), "Имя победителя — модель с наименьшей ошибкой на тесте."

